import {configured,login,logout,currentUser,memberships,rows,rpc,request} from './api.js';
import {queueMedia,pendingMedia,flushMedia,retryMedia} from './media-queue.js';
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
if(new URLSearchParams(location.search).get('mode')==='operacao'&&!location.hash)location.hash='palm';
const names={overview:['Visão da operação','◫'],maps:['Mapas e paletes','▤'],team:['Equipe e presença','♧'],dispatch:['Matriz e sorteio','⚖'],issues:['Conferências','☑'],catalogs:['Cadastros e layout','▦'],media:['Registro visual','▧'],integrations:['Integrações','⇄'],audit:['Eventos e auditoria','◷'],palm:['Minha operação','▣']};
const emptyData=()=>({"maps": [], "pallets": [], "memberships": [], "presence": [], "worker_skills": [], "skills": [], "assignments": [], "check_issues": [], "events": [], "priority_draws": [], "products": [], "vehicles": [], "vehicle_types": [], "addresses": [], "layout_versions": [], "palletization_versions": [], "effort_models": [], "loads": [], "media_records": [], "integration_jobs": [], "audit_log": []});
let pendingDispatchKey=null;
let demo=false,data=emptyData(),warehouseId=null,screen='overview',filter='',palmUser='u1';
const person=id=>data.memberships.find(u=>u.user_id===id)?.display_name||id;
const mapOf=p=>data.maps.find(m=>m.id===p.map_id)?.code||'—';
const presence=u=>data.presence.find(p=>p.user_id===u&&!p.ends_at)?.state||'absent';
const effort=u=>data.assignments.filter(a=>a.user_id===u&&a.state!=='cancelled').reduce((n,a)=>n+Number(a.standard_seconds),0);
const mins=s=>Math.round(Number(s)/60)+' min';
const labels={queued:'Na fila',assigned:'Em montagem',building:'Em montagem',staged:'Em staging',loaded:'Carregado',available:'Disponível',busy:'Em atividade',break:'Em pausa',absent:'Ausente',open:'Pendente',resolved:'Resolvida',disabled:'Desativado',helper:'Ajudante',checker:'Conferente',forklift:'Empilhador',supervisor:'Supervisor',admin:'Administrador',recorder:'Registro visual',viewer:'Consulta'};
const tag=(s,cls='')=>`<span class="tag ${cls||(['queued','break','open','disabled'].includes(s)?'amber':'')}">${esc(labels[s]||s)}</span>`;
function toast(s){$('#toast').textContent=s;$('#toast').style.display='block';setTimeout(()=>$('#toast').style.display='none',4500);}
function event(type,id,payload){data.events.unshift({id:crypto.randomUUID(),event_type:type,entity_id:id,payload,occurred_at:new Date().toISOString()});}
function dialog(title,html,save){$('#dialog-body').innerHTML=`<h2>${esc(title)}</h2>${html}`;$('#dialog').showModal();$('#dialog-form').onsubmit=async e=>{e.preventDefault();const b=e.submitter;b.disabled=true;try{await save(new FormData(e.target));$('#dialog').close();render();}catch(err){toast(err.message);}finally{b.disabled=false;}};}
$('#cancel').onclick=()=>$('#dialog').close();$('#menu').onclick=()=>document.body.classList.toggle('menu');$('#mobile-mode').onclick=()=>location.hash=screen==='palm'?'overview':'palm';
async function refresh(){if(demo||!currentUser())return;const tables=Object.keys(emptyData()).filter(x=>x!=='memberships');const result=await Promise.all(tables.map(async t=>[t,await rows(t,warehouseId)]));data=Object.fromEntries(result);data.memberships=(await memberships()).filter(m=>m.warehouse_id===warehouseId);}
async function enterLive(){if(!configured){toast('O banco exclusivo aguarda a conexão da nova conta Supabase. Você está na demonstração.');return;}
 dialog('Entrar no WMS',`<label>Usuário</label><input name="email" type="text" required autocomplete="username" autocapitalize="none" spellcheck="false"><label>Senha</label><input name="password" type="password" required autocomplete="current-password">`,async f=>{await login(f.get('email'),f.get('password'));const all=await memberships();const own=all.filter(m=>m.user_id===currentUser().id);if(!own.length){await logout();throw Error('Seu usuário ainda não foi vinculado ao armazém. Solicite a liberação ao administrador.');}warehouseId=own[0].warehouse_id;demo=false;await refresh();});}
const table=(heads,body)=>`<div class="table-wrap"><table><thead><tr>${heads.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${body||`<tr><td colspan="${heads.length}" class="empty">Nenhum registro neste ambiente.</td></tr>`}</tbody></table></div>`;
function overview(){const active=data.pallets.filter(p=>['assigned','building'].includes(p.state)).length;return `<div class="section-top"><div><h2>O turno, em um só lugar.</h2><p>Acompanhe o trabalho e distribua a próxima montagem.</p></div><button class="primary" data-action="dispatch">Sortear próxima montagem ↗</button></div><div class="stats">${[['Paletes na fila',data.pallets.filter(p=>p.state==='queued').length,'Aguardando atribuição','▤'],['Em montagem',active,'Trabalho físico em andamento','▥'],['Pessoas disponíveis',data.memberships.filter(u=>presence(u.user_id)==='available'&&u.role==='helper').length,'Presença atualizada no turno','♧'],['Pendências abertas',data.check_issues.filter(i=>i.state==='open').length,'Tratadas sem interromper a equipe','☑']].map(([l,v,s,i])=>`<div class="stat"><em>${i}</em><span class="label">${l}</span><strong>${v}</strong><small>${s}</small></div>`).join('')}</div><div class="grid"><section class="card"><div class="card-head"><h2>Próximos mapas</h2><small>MATRIZ DE PRIORIZAÇÃO</small></div>${mapTable()}<div class="card-body sub">A prioridade do mapa sempre vem antes do sorteio de pessoas.</div></section><section class="card"><div class="card-head"><h2>Equipe no turno</h2><a href="#team" class="sub">Ver equipe ↗</a></div>${data.memberships.slice(0,5).map(u=>`<div class="list-row"><span class="person">${esc(u.display_name.split(' ').map(s=>s[0]).slice(0,2).join(''))}</span><div class="grow"><b>${esc(u.display_name)}</b><small>${esc(labels[u.role])} · ${mins(effort(u.user_id))} atribuídos</small></div>${tag(presence(u.user_id))}</div>`).join('')}</section></div><div class="grid"><section class="card"><div class="card-head"><h2>Fluxo da operação</h2><small>FÍSICO E SISTÊMICO INDEPENDENTES</small></div><div class="step-flow">${[['queued','Na fila'],['assigned','Montagem'],['staged','Staging'],['loaded','Carregado']].map(([s,l])=>`<div class="step"><b>${data.pallets.filter(p=>p.state===s).length}</b><small>${l}</small></div>`).join('')}</div></section><section class="callout"><b>Operação contínua</b><br>Uma divergência fica pendente para ajudante e conferente. Ambos podem seguir outras tarefas e voltar para corrigir depois.</section></div>`;}
function mapTable(){return table(['Prioridade','Mapa','Paletes','Andamento'],[...data.maps].sort((a,b)=>b.priority-a.priority).map(m=>{const ps=data.pallets.filter(p=>p.map_id===m.id),done=ps.filter(p=>['staged','loaded'].includes(p.state)).length;return `<tr><td><span class="badge-number">${m.priority}</span></td><td><b>${esc(m.code)}</b><small>${esc(m.priority_reason)}</small></td><td>${ps.length}</td><td>${done}/${ps.length}<div class="progress"><i style="width:${ps.length?done/ps.length*100:0}%"></i></div></td></tr>`;}).join(''));}
function maps(){return `<div class="section-top"><div><h2>Fila de montagem</h2><p>Ordem definida pela Matriz de Priorização.</p></div><button class="primary" data-action="dispatch">Sortear próximo</button></div><section class="card">${mapTable()}</section><div class="section-top"><h2>Paletes</h2></div><section class="card">${table(['Palete','Mapa','Esforço padrão','Situação','Pessoa'],data.pallets.filter(p=>(p.code+mapOf(p)).includes(filter)).map(p=>`<tr><td><b>${esc(p.code)}</b></td><td>${esc(mapOf(p))}</td><td>${mins(p.standard_seconds)}</td><td>${tag(p.state)}</td><td>${esc(person(data.assignments.find(a=>a.pallet_id===p.id)?.user_id)||'—')}</td></tr>`).join(''))}</section>`;}
function team(){return `<div class="section-top"><div><h2>Presença dinâmica</h2><p>A presença muda ao longo do turno e é considerada em cada atribuição.</p></div></div><section class="card">${table(['Pessoa','Função','Habilidades','Esforço','Presença'],data.memberships.map(u=>`<tr><td><b>${esc(u.display_name)}</b></td><td>${esc(labels[u.role])}</td><td>${data.worker_skills.filter(s=>s.user_id===u.user_id).map(s=>esc(data.skills.find(k=>k.id===s.skill_id)?.name||'Habilidade')).join(', ')||'—'}</td><td>${mins(effort(u.user_id))}</td><td><button data-action="presence" data-id="${esc(u.user_id)}">${esc(labels[presence(u.user_id)])} ▾</button></td></tr>`).join(''))}</section><div class="callout">O esforço é contabilizado em segundos padrão. A calibração com históricos gera uma nova versão do modelo, preservando as atribuições anteriores.</div>`;}
function dispatchView(){return `<div class="section-top"><div><h2>Priorizar. Equilibrar. Sortear.</h2><p>Sorteio real entre pessoas elegíveis dentro da faixa de equilíbrio.</p></div><button class="primary" data-action="dispatch">Executar sorteio</button></div><section class="card"><div class="step-flow"><div class="step"><b>01</b><small>Maior prioridade</small></div><div class="step"><b>02</b><small>Presença + habilidade</small></div><div class="step"><b>03</b><small>Disponibilidade</small></div><div class="step"><b>04</b><small>Esforço + sorteio</small></div></div><div class="card-body sub">Faixa inicial: menor esforço acumulado + 600 segundos. Parâmetro inicial de implementação, sujeito à validação operacional.</div></section><div class="section-top"><h2>Histórico de sorteios</h2></div><section class="card">${table(['Mapa / palete','Selecionado','Elegíveis na faixa','Prioridade'],data.priority_draws.map(d=>{const p=data.pallets.find(p=>p.id===d.pallet_id);return `<tr><td>${esc(p?mapOf(p)+' / '+p.code:d.pallet_id)}</td><td>${esc(person(d.selected_user))}</td><td>${d.candidates?.length||0}</td><td>${d.priority_snapshot?.priority||'—'}</td></tr>`;}).join(''))}</section>`;}
function issues(){return `<div class="section-top"><div><h2>Pendências de conferência</h2><p>Corrija aqui, a qualquer momento, sem interromper as outras tarefas.</p></div><button class="primary" data-action="issue">Registrar divergência</button></div><section class="card">${table(['Palete','Divergência','Responsáveis','Situação',''],data.check_issues.map(i=>`<tr><td><b>${esc(data.pallets.find(p=>p.id===i.pallet_id)?.code||i.pallet_id)}</b></td><td>${esc(i.note)}<small>${esc(i.quantity||'')} ${i.quantity?'CX':''}</small></td><td>${esc(person(i.helper_id))}<small>${esc(person(i.checker_id))}</small></td><td>${tag(i.state)}</td><td>${i.state==='open'?`<button data-action="resolve" data-id="${esc(i.id)}">Corrigir</button>`:esc(i.resolution)}</td></tr>`).join(''))}</section>`;}
const catalogDefs={products:['Produtos','SKU, unidade e descrição'],palletization_versions:['Paletização','Camadas, lastro, peso e volume'],vehicles:['Veículos','Placas e tipo de veículo'],vehicle_types:['Capacidades','Peso, volume e posições'],layout_versions:['Layout versionado','Versões publicadas imutáveis'],addresses:['Endereços','Picking, staging, docas e estoque'],skills:['Habilidades','Matriz de qualificação'],effort_models:['Modelos de esforço','Segundos padrão e calibração'],loads:['Cargas','Vínculos de mapas e veículos']};
function catalogs(){return `<div class="section-top"><div><h2>Fundação do armazém</h2><p>Cadastros separados dos sistemas existentes. Os CSVs anteriores ainda não foram importados.</p></div></div><div class="catalogs">${Object.entries(catalogDefs).map(([k,[n,d]])=>`<button data-action="catalog" data-id="${k}"><b>${n} <span class="tag gray">${data[k].length}</span></b><small>${d}</small></button>`).join('')}</div><div class="callout">O endereço e os parâmetros usados por um palete permanecem vinculados à sua versão histórica. Uma mudança no layout não reescreve o trabalho já realizado.</div>`;}
function integrations(){return `<div class="section-top"><div><h2>Agentes e integrações</h2><p>Contratos preparados. Nenhum agente externo está conectado nesta etapa.</p></div></div><section class="card">${['Romaneio','Cora','OCP','Promax · 03.11.20'].map(n=>`<div class="list-row"><span class="person">⇄</span><div class="grow"><b>${n}</b><small>${n.startsWith('Promax')?'Carga Montada e Carregamento · implementação futura':'Contrato de jobs, estado e idempotência'}</small></div>${tag('disabled')}</div>`).join('')}</section><div class="callout">Promax permanece desativado. Resultado externo incerto vai para revisão manual; repetir um job exige reconciliação para evitar confirmação duplicada.</div><section class="card">${table(['Adaptador','Operação','Tentativas','Estado'],data.integration_jobs.map(j=>`<tr><td>${esc(j.adapter)}</td><td>${esc(j.operation)}</td><td>${j.attempts}/${j.max_attempts}</td><td>${tag(j.state)}</td></tr>`).join(''))}</section>`;}
function audit(){return `<div class="section-top"><h2>Linha do tempo operacional</h2></div><section class="card">${table(['Horário','Evento','Entidade'],data.events.map(e=>`<tr><td>${new Date(e.occurred_at).toLocaleString('pt-BR',{timeZone:'America/Sao_Paulo'})}</td><td>${esc(e.event_type)}</td><td>${esc(e.entity_id)}</td></tr>`).join(''))}</section><div class="callout">Em produção, as alterações geram trilha de auditoria no banco. Eventos e auditoria não podem ser editados pelo aplicativo.</div>`;}
function palm(){const uid=demo?palmUser:currentUser()?.id;const a=data.assignments.find(a=>a.user_id===uid&&a.state==='active'),p=data.pallets.find(p=>p.id===a?.pallet_id);return `<div class="palm-shell"><div class="section-top"><div><h2>Olá, ${esc(person(uid))}</h2><p>Uma tarefa por vez. Pendências ficam acessíveis.</p></div>${tag(presence(uid))}</div>${demo?`<select id="palm-user">${data.memberships.filter(u=>u.role==='helper').map(u=>`<option value="${u.user_id}" ${uid===u.user_id?'selected':''}>${esc(u.display_name)}</option>`).join('')}</select>`:''}<div class="pallet-card" style="margin-top:16px">${p?`<span class="eyebrow">MAPA ${esc(mapOf(p))}</span><h2>${esc(p.code)}</h2><div class="chips">${tag(p.state)}<span class="badge-number">${mins(p.standard_seconds)} padrão</span></div><p class="sub">Conclua a montagem e informe a posição de staging.</p><button class="primary" data-action="complete" data-id="${esc(p.id)}">Concluir montagem →</button><button data-action="capture" data-id="${esc(p.id)}">Adicionar foto ou vídeo</button>`:`<h2>Pronto para começar</h2><p class="sub">Sua próxima montagem aparecerá aqui após o sorteio.</p><button data-action="refresh">Atualizar tarefas</button>`}</div><h3>Minhas pendências</h3>${data.check_issues.filter(i=>i.helper_id===uid&&i.state==='open').map(i=>`<div class="list-row"><div class="grow"><b>${esc(i.note)}</b><small>Aguardando correção com o conferente</small></div>${tag('open')}</div>`).join('')||'<p class="sub">Nenhuma pendência aberta.</p>'}</div>`;}
async function media(){const entries=(await pendingMedia()).filter(e=>e.demo===demo&&(demo||e.owner===currentUser()?.id));return `<div class="section-top"><div><h2>Registro visual</h2><p>Arquivos enviados em segundo plano. Histórico consultado por mapa e palete.</p></div><button class="primary" data-action="capture">Adicionar registro</button></div><section class="card">${table(['Arquivo','Origem','Situação',''],entries.map(e=>`<tr><td>${esc(e.file.name)}<small>${(e.file.size/1048576).toFixed(1)} MB</small></td><td>${esc(e.palletId||e.loadId||'—')}</td><td>${tag(e.demo?'Local · demonstração':e.state==='failed'?'Falha no envio':'Na fila',e.state==='failed'?'amber':'gray')}</td><td>${!e.demo&&e.state==='failed'?`<button data-action="retry-media" data-id="${e.id}">Tentar novamente</button>`:''}</td></tr>`).join(''))}</section><div class="callout">${demo?'Na demonstração, os arquivos ficam somente neste dispositivo. Não há upload para servidor.':'Envio com repetição automática e preservação local até a confirmação.'} A lista carrega metadados; fotos e vídeos não pesam na tela operacional.</div><form id="media-search" class="toolbar"><input name="q" value="${esc(filter)}" placeholder="Buscar por legenda, mapa ou palete" aria-label="Buscar registro visual"><button>Buscar</button></form><section class="card">${table(['Registro','Palete / carga','Situação',''],data.media_records.filter(m=>{const p=data.pallets.find(p=>p.id===m.pallet_id);return (m.caption+' '+(p?.code||'')+' '+(p?mapOf(p):'')+' '+(m.load_id||'')).toLowerCase().includes(filter.toLowerCase());}).map(m=>`<tr><td>${esc(m.caption)}<small>${esc(m.content_type)}</small></td><td>${esc(m.pallet_id||m.load_id)}</td><td>${tag(m.state)}</td><td>${m.state==='uploaded'?`<button data-action="view-media" data-id="${m.id}">Abrir</button>`:''}</td></tr>`).join(''))}</section>`;}
async function render(){screen=location.hash.slice(1)||'overview';if(!names[screen])screen='overview';$('#title').textContent=names[screen][0];$('#nav').innerHTML=Object.entries(names).map(([k,[n,i]])=>`<a href="#${k}" class="${k===screen?'active':''}"><span>${i}</span>${n}</a>`).join('');$('#environment').innerHTML=demo?`<span>◉</span><span><b>Demonstração da fundação</b> · Dados fictícios. Banco exclusivo criado · entre para acessar dados reais.</span><button data-action="live">Entrar na operação</button>`:`<span>◉</span><span><b>Operação conectada</b> · ${esc(person(currentUser()?.id))}</span><button data-action="logout">Sair</button>`;if(!currentUser()){$('#environment').innerHTML='<span>Acesso restrito à equipe do armazém</span>';$('#content').innerHTML='<section class="card"><div class="card-body"><h2>Bem-vinda ao WMS</h2><p>Entre com seu usuário e senha para acessar a operação.</p><button class="primary" data-action="live">Entrar na operação</button></div></section>';return;}$('#content').innerHTML=await ({overview,maps,team,dispatch:dispatchView,issues,catalogs,integrations,audit,palm,media}[screen])();$('#media-search')?.addEventListener('submit',e=>{e.preventDefault();filter=new FormData(e.target).get('q');render();});$('#palm-user')?.addEventListener('change',e=>{palmUser=e.target.value;render();});document.body.classList.remove('menu');}
async function doDispatch(){if(!demo){pendingDispatchKey??=crypto.randomUUID();const d=await rpc('dispatch_next',{w:warehouseId,request_key:pendingDispatchKey,balance_window:600});pendingDispatchKey=null;await refresh();toast(d.status==='no_work'?'Sem trabalho na fila':d.status==='awaiting_eligible_worker'?'Aguardando pessoa habilitada para o mapa prioritário':'Montagem atribuída');return;}
 const next=[...data.pallets].filter(p=>p.state==='queued'&&data.maps.find(m=>m.id===p.map_id)?.released).sort((a,b)=>data.maps.find(m=>m.id===b.map_id).priority-data.maps.find(m=>m.id===a.map_id).priority)[0];if(!next)return toast('Não há paletes na fila');
 let pool=data.memberships.filter(u=>u.active&&u.role==='helper'&&presence(u.user_id)==='available'&&data.worker_skills.some(s=>s.user_id===u.user_id&&s.skill_id===next.skill_id));if(!pool.length)return toast('Mapa prioritário aguardando pessoa habilitada e disponível');const min=Math.min(...pool.map(u=>effort(u.user_id)));pool=pool.filter(u=>effort(u.user_id)<=min+600);
 const random=new Uint32Array(1);let v;const ceiling=Math.floor(4294967296/pool.length)*pool.length;do{crypto.getRandomValues(random);v=random[0];}while(v>=ceiling);const u=pool[v%pool.length],draw={id:crypto.randomUUID(),pallet_id:next.id,selected_user:u.user_id,candidates:pool.map(u=>({user_id:u.user_id,effort_seconds:effort(u.user_id)})),priority_snapshot:{priority:data.maps.find(m=>m.id===next.map_id).priority}};data.priority_draws.unshift(draw);data.assignments.push({pallet_id:next.id,user_id:u.user_id,standard_seconds:next.standard_seconds,state:'active',draw_id:draw.id});next.state='assigned';data.presence.find(p=>p.user_id===u.user_id&&!p.ends_at).state='busy';event('assigned',next.id,{user_id:u.user_id});toast(`${next.code} · Mapa ${mapOf(next)} → ${u.display_name}`);}
document.addEventListener('click',async e=>{const b=e.target.closest('[data-action]');if(!b)return;const a=b.dataset.action,id=b.dataset.id;b.disabled=true;try{
 if(a==='live')return enterLive();if(!currentUser())return enterLive();if(a==='logout'){await logout();demo=false;warehouseId=null;data=emptyData();}
 if(a==='refresh'){await refresh();toast('Tarefas atualizadas');}if(a==='dispatch')await doDispatch();
 if(a==='presence')return dialog('Atualizar presença',`<label>Estado</label><select name="state">${['available','break','absent'].map(s=>`<option value="${s}">${labels[s]}</option>`).join('')}</select><label>Turno</label><select name="shift"><option>A</option><option>B</option><option selected>C</option></select>`,async f=>{if(demo){if(data.assignments.some(a=>a.user_id===id&&a.state==='active')&&f.get('state')==='available')throw Error('Conclua a tarefa antes de voltar a disponível');data.presence=data.presence.filter(p=>p.user_id!==id);data.presence.push({user_id:id,state:f.get('state'),shift:f.get('shift'),ends_at:null});event('presence_changed',id,{state:f.get('state')});}else{await rpc('set_presence',{w:warehouseId,target:id,new_state:f.get('state'),shift_code:f.get('shift')});await refresh();}});
 if(a==='issue'){const ps=data.pallets.filter(p=>data.assignments.some(a=>a.pallet_id===p.id));if(!ps.length)throw Error('Atribua um palete antes de registrar uma divergência');return dialog('Registrar divergência',`<label>Palete</label><select name="p">${ps.map(p=>`<option value="${p.id}">${esc(p.code)} · ${esc(mapOf(p))}</option>`).join('')}</select><label>Tipo</label><select name="kind"><option value="shortage">Falta</option><option value="excess">Sobra</option><option value="damage">Avaria</option><option value="other">Outro</option></select><label>Quantidade</label><input name="qty" type="number" min="1" required><label>Descrição</label><textarea name="note" required></textarea>`,async f=>{if(demo){const p=f.get('p');data.check_issues.unshift({id:crypto.randomUUID(),pallet_id:p,helper_id:data.assignments.find(a=>a.pallet_id===p).user_id,checker_id:'u3',state:'open',note:f.get('note'),quantity:Number(f.get('qty'))});event('issue_opened',p,{});}else{await rpc('report_issue',{w:warehouseId,p:f.get('p'),kind:f.get('kind'),qty:Number(f.get('qty')),note:f.get('note')});await refresh();}});}
 if(a==='resolve')return dialog('Corrigir pendência','<label>Correção realizada</label><textarea name="resolution" required></textarea>',async f=>{if(demo){Object.assign(data.check_issues.find(i=>i.id===id),{state:'resolved',resolution:f.get('resolution')});event('issue_resolved',id,{});}else{await rpc('resolve_issue',{w:warehouseId,issue:id,resolution:f.get('resolution')});await refresh();}});
 if(a==='complete'){const staging=data.addresses.filter(s=>s.zone==='staging');if(!staging.length)throw Error('Cadastre e publique as posições de staging');return dialog('Concluir montagem',`<label>Posição de staging</label><select name="staging">${staging.map(s=>`<option value="${s.id}">${esc(s.code)}</option>`).join('')}</select><p class="sub">Pendências continuam abertas para tratamento posterior.</p>`,async f=>{if(demo){const as=data.assignments.find(a=>a.pallet_id===id&&a.state==='active');as.state='completed';data.pallets.find(p=>p.id===id).state='staged';data.presence.find(p=>p.user_id===as.user_id&&!p.ends_at).state='available';event('staged',id,{staging:f.get('staging')});}else{await rpc('complete_pallet',{w:warehouseId,p:id,staging:f.get('staging')});await refresh();}});}
 if(a==='catalog'){return dialog(catalogDefs[id][0],data[id].length?`<div class="detail">${data[id].map(r=>`<p>${esc(r.sku||r.code||r.name||r.plate||'Versão '+r.version)}</p>`).join('')}</div>`:'<p class="sub">Cadastro vazio. A estrutura do banco está preparada; importação e telas de edição serão conectadas ao projeto exclusivo.</p>',async()=>{});}
 if(a==='capture'){if(!data.pallets.length)throw Error('Selecione um palete existente');return dialog('Adicionar registro visual',`<label>Palete</label><select name="pallet">${data.pallets.map(p=>`<option value="${p.id}" ${p.id===id?'selected':''}>${esc(p.code)} · ${esc(mapOf(p))}</option>`).join('')}</select><label>Foto ou vídeo</label><input name="file" type="file" accept="image/jpeg,image/png,image/webp,video/mp4" required><p class="sub">Até 50 MB. O envio não bloqueia a montagem.</p>`,async f=>{await queueMedia({file:f.get('file'),warehouseId:warehouseId||'demo',palletId:f.get('pallet'),demo});toast(demo?'Registro salvo localmente na demonstração':'Registro na fila de envio');void flushMedia();});}
 if(a==='view-media'){const m=data.media_records.find(m=>m.id===id);const r=await request('/storage/v1/object/sign/wms-evidence/'+m.object_path,{method:'POST',body:{expiresIn:60}});const {config}=await import('./config.js');const url=new URL('/storage/v1'+r.signedURL,config.supabaseUrl).href;return dialog('Registro visual',m.content_type.startsWith('video/')?`<video controls src="${esc(url)}" style="max-width:100%"></video>`:`<img alt="${esc(m.caption)}" src="${esc(url)}" style="max-width:100%">`,async()=>{});}
 if(a==='retry-media')await retryMedia(id);await render();
 }catch(err){toast(err.message);}finally{b.disabled=false;}});
